package com.fream.back.domain.order.repository;

import com.fream.back.domain.order.dto.OrderBidResponseDto;
import com.fream.back.domain.order.dto.OrderBidStatusCountDto;
import com.fream.back.domain.order.entity.BidStatus;
import com.fream.back.domain.order.entity.QOrder;
import com.fream.back.domain.order.entity.QOrderBid;
import com.fream.back.domain.product.entity.QProduct;
import com.fream.back.domain.product.entity.QProductColor;
import com.fream.back.domain.product.entity.QProductImage;
import com.fream.back.domain.product.entity.QProductSize;
import com.fream.back.domain.shipment.entity.QOrderShipment;
import com.fream.back.domain.user.entity.QUser;
import com.querydsl.core.BooleanBuilder;
import com.querydsl.core.Tuple;
import com.querydsl.core.types.Projections;
import com.querydsl.jpa.impl.JPAQueryFactory;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Repository;
import org.springframework.util.StringUtils;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * 주문 입찰 저장소 구현체
 */
@Repository
@RequiredArgsConstructor
public class OrderBidRepositoryImpl implements OrderBidRepositoryCustom {
    private final JPAQueryFactory queryFactory;

    @Override
    public Page<OrderBidResponseDto> findOrderBidsByFilters(String email, String bidStatus, String orderStatus, Pageable pageable) {
        QOrderBid orderBid = QOrderBid.orderBid;
        QOrder order = QOrder.order;
        QProductSize productSize = QProductSize.productSize;
        QProductColor productColor = QProductColor.productColor;
        QProduct product = QProduct.product;
        QProductImage productImage = QProductImage.productImage;
        QOrderShipment orderShipment = QOrderShipment.orderShipment;
        QUser user = QUser.user;

        // 조건 빌더 생성
        BooleanBuilder whereBuilder = new BooleanBuilder();

        // 이메일 조건 추가
        if (StringUtils.hasText(email)) {
            whereBuilder.and(user.email.eq(email));
        }

        // 입찰 상태 조건 추가
        if (StringUtils.hasText(bidStatus)) {
            whereBuilder.and(orderBid.status.stringValue().eq(bidStatus));
        }

        // 주문 상태 조건 추가
        if (StringUtils.hasText(orderStatus)) {
            whereBuilder.and(order.status.stringValue().eq(orderStatus));
        }

        // Main Query
        List<OrderBidResponseDto> content = queryFactory
                .select(Projections.constructor(
                        OrderBidResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(whereBuilder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        // Count Query
        Long total = queryFactory
                .select(orderBid.id.count())
                .from(orderBid)
                .join(orderBid.user, user)
                .leftJoin(orderBid.order, order)
                .where(whereBuilder)
                .fetchOne();

        return new PageImpl<>(content, pageable, total != null ? total : 0L);
    }

    @Override
    public OrderBidStatusCountDto countOrderBidsByStatus(String email) {
        QOrderBid orderBid = QOrderBid.orderBid;

        // 대기 중 상태 개수 조회
        Long pendingCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(BidStatus.PENDING)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();

        // 매칭 완료 상태 개수 조회
        Long matchedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(BidStatus.MATCHED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();

        // 취소 또는 완료 상태 개수 조회
        Long cancelledOrCompletedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.in(
                                BidStatus.CANCELLED, BidStatus.COMPLETED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();

        // null 값 처리
        pendingCount = pendingCount != null ? pendingCount : 0L;
        matchedCount = matchedCount != null ? matchedCount : 0L;
        cancelledOrCompletedCount = cancelledOrCompletedCount != null ? cancelledOrCompletedCount : 0L;

        return new OrderBidStatusCountDto(pendingCount, matchedCount, cancelledOrCompletedCount);
    }

    @Override
    public OrderBidResponseDto findOrderBidById(Long orderBidId, String email) {
        QOrderBid orderBid = QOrderBid.orderBid;
        QOrder order = QOrder.order;
        QProductSize productSize = QProductSize.productSize;
        QProductColor productColor = QProductColor.productColor;
        QProduct product = QProduct.product;
        QProductImage productImage = QProductImage.productImage;
        QOrderShipment orderShipment = QOrderShipment.orderShipment;
        QUser user = QUser.user;

        return queryFactory
                .select(Projections.constructor(
                        OrderBidResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(
                        orderBid.id.eq(orderBidId),
                        orderBid.user.email.eq(email)
                )
                .fetchOne();
    }

    @Override
    public Map<Long, Long> tradeCountByColorIds(List<Long> colorIds) {
        if (colorIds == null || colorIds.isEmpty()) {
            return Collections.emptyMap();
        }

        QOrderBid orderBid = QOrderBid.orderBid;
        QProductSize productSize = QProductSize.productSize;

        List<Tuple> results = queryFactory.select(
                        productSize.productColor.id,
                        orderBid.id.count()
                )
                .from(orderBid)
                .join(orderBid.productSize, productSize)
                .where(
                        productSize.productColor.id.in(colorIds),
                        orderBid.status.eq(BidStatus.COMPLETED)
                )
                .groupBy(productSize.productColor.id)
                .fetch();

        return results.stream()
                .collect(Collectors.toMap(
                        t -> t.get(productSize.productColor.id),
                        t -> t.get(orderBid.id.count())
                ));
    }
}----
package com.fream.back.domain.order.service.query;

import com.fream.back.domain.order.dto.OrderBidResponseDto;
import com.fream.back.domain.order.dto.OrderBidStatusCountDto;
import com.fream.back.domain.order.entity.OrderBid;
import com.fream.back.domain.order.exception.InvalidOrderBidDataException;
import com.fream.back.domain.order.exception.OrderBidAccessDeniedException;
import com.fream.back.domain.order.exception.OrderBidNotFoundException;
import com.fream.back.domain.order.repository.OrderBidRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

/**
 * 주문 입찰 조회 서비스
 */
@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)
@Slf4j
public class OrderBidQueryService {

    private final OrderBidRepository orderBidRepository;

    /**
     * ID로 주문 입찰을 조회합니다.
     *
     * @param id 주문 입찰 ID
     * @return 주문 입찰 (Optional)
     * @throws InvalidOrderBidDataException 주문 입찰 ID가 유효하지 않은 경우
     */
    public Optional<OrderBid> findById(Long id) {
        if (id == null) {
            throw new InvalidOrderBidDataException("주문 입찰 ID가 없습니다.");
        }
        return orderBidRepository.findById(id);
    }

    /**
     * 주문 ID로 주문 입찰을 조회합니다.
     *
     * @param orderId 주문 ID
     * @return 주문 입찰 (Optional)
     * @throws InvalidOrderBidDataException 주문 ID가 유효하지 않은 경우
     */
    public Optional<OrderBid> findByOrderId(Long orderId) {
        if (orderId == null) {
            throw new InvalidOrderBidDataException("주문 ID가 없습니다.");
        }
        return orderBidRepository.findByOrderId(orderId);
    }

    /**
     * 필터링된 주문 입찰 목록을 조회합니다.
     *
     * @param email 사용자 이메일
     * @param bidStatus 입찰 상태
     * @param orderStatus 주문 상태
     * @param pageable 페이징 정보
     * @return 주문 입찰 목록 (페이징)
     * @throws OrderBidAccessDeniedException 사용자 이메일이 유효하지 않을 경우
     * @throws InvalidOrderBidDataException 조회 중 오류가 발생한 경우
     */
    public Page<OrderBidResponseDto> getOrderBids(String email, String bidStatus, String orderStatus, Pageable pageable) {
        validateEmail(email);

        try {
            return orderBidRepository.findOrderBidsByFilters(email, bidStatus, orderStatus, pageable);
        } catch (Exception e) {
            log.error("주문 입찰 목록 조회 중 오류 발생: {}", e.getMessage(), e);
            throw new InvalidOrderBidDataException("주문 입찰 목록 조회 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

    /**
     * 사용자의 주문 입찰 상태별 개수를 조회합니다.
     *
     * @param email 사용자 이메일
     * @return 주문 입찰 상태별 개수
     * @throws OrderBidAccessDeniedException 사용자 이메일이 유효하지 않을 경우
     * @throws InvalidOrderBidDataException 조회 중 오류가 발생한 경우
     */
    public OrderBidStatusCountDto getOrderBidStatusCounts(String email) {
        validateEmail(email);

        try {
            return orderBidRepository.countOrderBidsByStatus(email);
        } catch (Exception e) {
            log.error("주문 입찰 상태별 개수 조회 중 오류 발생: {}", e.getMessage(), e);
            throw new InvalidOrderBidDataException("주문 입찰 상태별 개수 조회 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

    /**
     * 주문 입찰 상세 정보를 조회합니다.
     *
     * @param orderBidId 주문 입찰 ID
     * @param email 사용자 이메일
     * @return 주문 입찰 상세 정보 (Optional)
     * @throws OrderBidAccessDeniedException 사용자 이메일이 유효하지 않을 경우
     * @throws InvalidOrderBidDataException 주문 입찰 ID가 유효하지 않을 경우
     */
    public Optional<OrderBidResponseDto> getOrderBidDetail(Long orderBidId, String email) {
        if (orderBidId == null) {
            throw new InvalidOrderBidDataException("주문 입찰 ID가 없습니다.");
        }

        validateEmail(email);

        try {
            OrderBidResponseDto responseDto = orderBidRepository.findOrderBidById(orderBidId, email);
            return Optional.ofNullable(responseDto);
        } catch (Exception e) {
            log.error("주문 입찰 상세 정보 조회 중 오류 발생: {}", e.getMessage(), e);
            throw new InvalidOrderBidDataException("주문 입찰 상세 정보 조회 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

    /**
     * 이메일 유효성을 검사합니다.
     *
     * @param email 사용자 이메일
     * @throws OrderBidAccessDeniedException 이메일이 유효하지 않은 경우
     */
    private void validateEmail(String email) {
        if (email == null || email.trim().isEmpty()) {
            throw new OrderBidAccessDeniedException("사용자 이메일이 없습니다.");
        }
    }
}----
package com.fream.back.domain.order.controller.query;

import com.fream.back.domain.order.dto.OrderBidResponseDto;
import com.fream.back.domain.order.dto.OrderBidStatusCountDto;
import com.fream.back.domain.order.exception.InvalidOrderBidDataException;
import com.fream.back.domain.order.exception.OrderBidAccessDeniedException;
import com.fream.back.domain.order.exception.OrderBidNotFoundException;
import com.fream.back.domain.order.service.query.OrderBidQueryService;
import com.fream.back.global.dto.ResponseDto;
import com.fream.back.global.utils.SecurityUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * 주문 입찰 조회 컨트롤러
 */
@RestController
@RequestMapping("/order-bids")
@RequiredArgsConstructor
@Slf4j
public class OrderBidQueryController {

    private final OrderBidQueryService orderBidQueryService;

    /**
     * 주문 입찰 목록을 조회합니다.
     *
     * @param bidStatus 입찰 상태 필터
     * @param orderStatus 주문 상태 필터
     * @param pageable 페이징 정보
     * @return 주문 입찰 목록 (페이징)
     * @throws OrderBidAccessDeniedException 주문 입찰에 대한 접근 권한이 없는 경우
     * @throws InvalidOrderBidDataException 주문 입찰 정보가 유효하지 않은 경우
     */
    @GetMapping
    public ResponseEntity<ResponseDto<Page<OrderBidResponseDto>>> getOrderBids(
            @RequestParam(value = "bidStatus", required = false) String bidStatus,
            @RequestParam(value = "orderStatus", required = false) String orderStatus,
            Pageable pageable
    ) {
        // 사용자 이메일 추출 및 검증
        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 목록 조회");

        log.info("사용자 [{}]의 주문 입찰 목록을 조회합니다. 필터 - 입찰 상태: {}, 주문 상태: {}",
                email, bidStatus, orderStatus);

        Page<OrderBidResponseDto> result = orderBidQueryService.getOrderBids(email, bidStatus, orderStatus, pageable);

        return ResponseEntity.ok(ResponseDto.success(result, "주문 입찰 목록 조회 성공"));
    }

    /**
     * 주문 입찰 상태별 개수를 조회합니다.
     *
     * @return 주문 입찰 상태별 개수
     * @throws OrderBidAccessDeniedException 주문 입찰에 대한 접근 권한이 없는 경우
     */
    @GetMapping("/count")
    public ResponseEntity<ResponseDto<OrderBidStatusCountDto>> getOrderBidStatusCounts() {
        // 사용자 이메일 추출 및 검증
        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 상태별 개수 조회");

        log.info("사용자 [{}]의 주문 입찰 상태별 개수를 조회합니다.", email);

        OrderBidStatusCountDto result = orderBidQueryService.getOrderBidStatusCounts(email);

        return ResponseEntity.ok(ResponseDto.success(result, "주문 입찰 상태별 개수 조회 성공"));
    }

    /**
     * 주문 입찰 상세 정보를 조회합니다.
     *
     * @param orderBidId 주문 입찰 ID
     * @return 주문 입찰 상세 정보
     * @throws OrderBidAccessDeniedException 주문 입찰에 대한 접근 권한이 없는 경우
     * @throws OrderBidNotFoundException 주문 입찰을 찾을 수 없는 경우
     */
    @GetMapping("/{orderBidId}")
    public ResponseEntity<ResponseDto<OrderBidResponseDto>> getOrderBidDetail(@PathVariable("orderBidId") Long orderBidId) {
        // 사용자 이메일 추출 및 검증
        String email = SecurityUtils.extractAndValidateEmailForOrderBid("주문 입찰 상세 정보 조회");

        log.info("사용자 [{}]가 주문 입찰(ID: {})의 상세 정보를 조회합니다.", email, orderBidId);

        OrderBidResponseDto result = orderBidQueryService.getOrderBidDetail(orderBidId, email)
                .orElseThrow(() -> new OrderBidNotFoundException("해당 주문 입찰이 존재하지 않습니다(ID: " + orderBidId + ")"));

        return ResponseEntity.ok(ResponseDto.success(result, "주문 입찰 상세 정보 조회 성공"));
    }
}----
